T5="P1-M4-5"; T6="P1-M4-6"
Q=[
# ---------- M4-5: Poder Legislativo ----------
(T5,["44"],"C","O Poder Legislativo é exercido pelo Congresso Nacional, que se compõe da Câmara dos Deputados e do Senado Federal, e cada legislatura terá a duração de quatro anos.","Art. 44, caput e p.ú.","leitura"),
(T5,["45"],"E","A Câmara dos Deputados compõe-se de representantes dos Estados, eleitos pelo princípio majoritário.","Art. 45: representantes do povo, eleitos pelo sistema proporcional. Senado: representantes dos Estados e do DF, princípio majoritário (art. 46).","confusao"),
(T5,["45"],"C","O número total de Deputados, bem como a representação por Estado e pelo Distrito Federal, será estabelecido por lei complementar, proporcionalmente à população, de modo que nenhuma unidade da Federação tenha menos de oito ou mais de setenta Deputados.","Art. 45, §1º.","numero"),
(T5,["45"],"E","Cada Território Federal elegerá dois Deputados.","Art. 45, §2º: quatro Deputados.","numero"),
(T5,["46"],"C","Cada Estado e o Distrito Federal elegerão três Senadores, com mandato de oito anos, e a representação de cada unidade será renovada de quatro em quatro anos, alternadamente, por um e por dois terços.","Art. 46, §§1º e 2º.","numero"),
(T5,["46"],"E","Cada Senador será eleito com um suplente.","Art. 46, §3º: dois suplentes.","numero"),
(T5,["47"],"C","Salvo disposição constitucional em contrário, as deliberações de cada Casa e de suas Comissões serão tomadas por maioria dos votos, presente a maioria absoluta de seus membros.","Art. 47.","quorum"),
(T5,["47"],"E","As deliberações de cada Casa serão tomadas, salvo disposição em contrário, por maioria absoluta dos votos, presente um terço de seus membros.","Art. 47: maioria dos votos (simples), presente a maioria absoluta.","quorum"),
(T5,["49"],"C","É da competência exclusiva do Congresso Nacional resolver definitivamente sobre tratados, acordos ou atos internacionais que acarretem encargos ou compromissos gravosos ao patrimônio nacional.","Art. 49, I.","competencia"),
(T5,["49"],"E","Compete ao Congresso Nacional, mediante lei sancionada pelo Presidente da República, autorizar este e o Vice-Presidente a se ausentarem do País por mais de quinze dias.","Art. 49, III: competência exclusiva, por decreto legislativo (sem sanção).","competencia"),
(T5,["49"],"E","É competência exclusiva do Congresso Nacional autorizar o Presidente da República a se ausentar do País quando a ausência exceder a trinta dias.","Art. 49, III: quinze dias.","numero"),
(T5,["49"],"C","Compete exclusivamente ao Congresso Nacional sustar os atos normativos do Poder Executivo que exorbitem do poder regulamentar ou dos limites de delegação legislativa.","Art. 49, V.","competencia"),
(T5,["49"],"C","Compete exclusivamente ao Congresso Nacional fixar idêntico subsídio para os Deputados Federais e os Senadores.","Art. 49, VII (EC 19/1998 — por decreto legislativo).","competencia"),
(T5,["49"],"E","Compete ao Congresso Nacional julgar, a cada dois anos, as contas prestadas pelo Presidente da República.","Art. 49, IX: anualmente.","numero"),
(T5,["49"],"C","Compete exclusivamente ao Congresso Nacional escolher dois terços dos membros do Tribunal de Contas da União.","Art. 49, XIII.","competencia"),
(T5,["49"],"C","É competência exclusiva do Congresso Nacional autorizar referendo e convocar plebiscito.","Art. 49, XV.","competencia"),
(T5,["49"],"E","Compete à Câmara dos Deputados, e não ao Congresso Nacional, aprovar previamente a alienação ou concessão de terras públicas com área superior a dois mil e quinhentos hectares.","Art. 49, XVII: competência exclusiva do Congresso Nacional.","competencia"),
(T5,["50"],"C","A Câmara dos Deputados, o Senado Federal ou qualquer de suas Comissões poderão convocar Ministro de Estado para prestar, pessoalmente, informações sobre assunto previamente determinado, importando crime de responsabilidade a ausência sem justificação adequada.","Art. 50, caput.","competencia"),
(T5,["50"],"E","As Mesas da Câmara e do Senado poderão encaminhar pedidos escritos de informação a Ministros de Estado, importando crime de responsabilidade o não atendimento no prazo de quinze dias.","Art. 50, §2º: trinta dias.","numero"),
(T5,["51"],"C","Compete privativamente à Câmara dos Deputados autorizar, por dois terços de seus membros, a instauração de processo contra o Presidente e o Vice-Presidente da República e os Ministros de Estado.","Art. 51, I.","quorum"),
(T5,["51"],"E","Compete privativamente à Câmara dos Deputados processar e julgar o Presidente da República nos crimes de responsabilidade.","Art. 52, I: competência do Senado Federal; à Câmara cabe autorizar a instauração do processo.","competencia"),
(T5,["51"],"C","Compete privativamente à Câmara dos Deputados proceder à tomada de contas do Presidente da República, quando não apresentadas ao Congresso Nacional dentro de sessenta dias após a abertura da sessão legislativa.","Art. 51, II.","prazo"),
(T5,["51"],"C","Compete privativamente à Câmara dos Deputados elaborar seu regimento interno e dispor sobre sua organização, funcionamento, polícia, criação, transformação ou extinção dos cargos, empregos e funções de seus serviços.","Art. 51, III e IV.","competencia"),
(T5,["52"],"E","Compete privativamente ao Senado Federal autorizar a instauração de processo contra o Presidente da República por crime de responsabilidade.","Art. 51, I: autorizar a instauração é da Câmara (2/3); o Senado processa e julga (art. 52, I).","competencia"),
(T5,["52"],"C","Compete privativamente ao Senado Federal processar e julgar os Ministros do Supremo Tribunal Federal, os membros do CNJ e do CNMP, o Procurador-Geral da República e o Advogado-Geral da União nos crimes de responsabilidade.","Art. 52, II.","competencia"),
(T5,["52"],"E","Nos julgamentos do Presidente da República por crime de responsabilidade, funcionará como Presidente do Senado o Presidente do STF, e a condenação, que somente será proferida pela maioria absoluta dos votos do Senado, limitar-se-á à perda do cargo.","Art. 52, p.ú.: dois terços dos votos; perda do cargo com inabilitação por oito anos para função pública.","quorum"),
(T5,["52"],"C","A condenação por crime de responsabilidade do Presidente da República limita-se à perda do cargo, com inabilitação, por oito anos, para o exercício de função pública, sem prejuízo das demais sanções judiciais cabíveis.","Art. 52, p.ú.","leitura"),
(T5,["52"],"E","A aprovação prévia pelo Senado Federal da escolha dos chefes de missão diplomática de caráter permanente ocorre por voto aberto, após arguição pública.","Art. 52, IV: voto secreto, após arguição em sessão secreta.","pegadinha"),
(T5,["52"],"C","Compete privativamente ao Senado Federal suspender a execução, no todo ou em parte, de lei declarada inconstitucional por decisão definitiva do STF.","Art. 52, X.","competencia"),
(T5,["52"],"C","Compete privativamente ao Senado Federal autorizar operações externas de natureza financeira de interesse da União, dos Estados, do DF, dos Territórios e dos Municípios.","Art. 52, V.","competencia"),
(T5,["57"],"C","O Congresso Nacional reunir-se-á anualmente, na Capital Federal, de 2 de fevereiro a 17 de julho e de 1º de agosto a 22 de dezembro.","Art. 57, caput (EC 50/2006).","prazo"),
(T5,["57"],"E","O Congresso Nacional reunir-se-á anualmente de 15 de fevereiro a 30 de junho e de 1º de agosto a 15 de dezembro.","Art. 57, caput: datas anteriores à EC 50/2006; hoje, 2/2 a 17/7 e 1º/8 a 22/12.","prazo"),
(T5,["57"],"C","A sessão legislativa não será interrompida sem a aprovação do projeto de lei de diretrizes orçamentárias.","Art. 57, §2º.","leitura"),
(T5,["57"],"C","A Câmara dos Deputados e o Senado Federal reunir-se-ão em sessão conjunta para inaugurar a sessão legislativa, elaborar o regimento comum, receber o compromisso do Presidente e do Vice-Presidente da República e conhecer do veto e sobre ele deliberar.","Art. 57, §3º.","competencia"),
(T5,["57"],"E","No primeiro ano da legislatura, cada Casa reunir-se-á em sessões preparatórias, a partir de 1º de fevereiro, para a posse de seus membros e eleição das respectivas Mesas, para mandato de dois anos, permitida a recondução ao mesmo cargo na eleição imediatamente subsequente.","Art. 57, §4º: vedada a recondução para o mesmo cargo na eleição imediatamente subsequente.","pegadinha"),
(T5,["57"],"C","A Mesa do Congresso Nacional será presidida pelo Presidente do Senado Federal, e os demais cargos serão exercidos, alternadamente, pelos ocupantes de cargos equivalentes na Câmara dos Deputados e no Senado Federal.","Art. 57, §5º.","competencia"),
(T5,["57"],"E","A convocação extraordinária do Congresso Nacional, em caso de urgência ou interesse público relevante, far-se-á exclusivamente pelo Presidente da República.","Art. 57, §6º, II: também pelos Presidentes da Câmara e do Senado ou a requerimento da maioria dos membros de ambas as Casas, com aprovação da maioria absoluta de cada Casa.","generalizacao"),
(T5,["57"],"C","Na sessão legislativa extraordinária, o Congresso Nacional somente deliberará sobre a matéria para a qual foi convocado, vedado o pagamento de parcela indenizatória em valor superior ao subsídio mensal.","Art. 57, §7º.","leitura"),
(T5,["58"],"C","Na constituição das Mesas e de cada Comissão, é assegurada, tanto quanto possível, a representação proporcional dos partidos ou dos blocos parlamentares que participem da respectiva Casa.","Art. 58, §1º.","leitura"),
(T5,["58"],"C","Às comissões cabe discutir e votar projeto de lei que dispensar, na forma do regimento, a competência do Plenário, salvo se houver recurso de um décimo dos membros da Casa.","Art. 58, §2º, I.","quorum"),
(T5,["58"],"E","As comissões parlamentares de inquérito serão criadas mediante requerimento de dois terços dos membros da Casa, para a apuração de fato determinado e por prazo certo.","Art. 58, §3º: um terço dos membros.","numero"),
(T5,["58"],"C","As comissões parlamentares de inquérito terão poderes de investigação próprios das autoridades judiciais, além de outros previstos nos regimentos das respectivas Casas, e suas conclusões serão encaminhadas ao Ministério Público, se for o caso.","Art. 58, §3º.","leitura"),
(T5,["58"],"E","Durante o recesso, haverá uma Comissão representativa do Congresso Nacional, cuja composição não precisa reproduzir a proporcionalidade da representação partidária.","Art. 58, §4º: reproduzirá, quanto possível, a proporcionalidade.","pegadinha"),
(T5,["59"],"C","O processo legislativo compreende a elaboração de emendas à Constituição, leis complementares, leis ordinárias, leis delegadas, medidas provisórias, decretos legislativos e resoluções.","Art. 59.","leitura"),
(T5,["61"],"C","A iniciativa das leis complementares e ordinárias cabe a qualquer membro ou Comissão da Câmara dos Deputados, do Senado Federal ou do Congresso Nacional, ao Presidente da República, ao STF, aos Tribunais Superiores, ao Procurador-Geral da República e aos cidadãos.","Art. 61, caput.","iniciativa"),
(T5,["61"],"E","É de iniciativa privativa do Presidente da República a lei que disponha sobre a criação de cargos, funções ou empregos públicos em qualquer dos Poderes.","Art. 61, §1º, II, a: na administração direta e autárquica.","generalizacao"),
(T5,["61"],"C","São de iniciativa privativa do Presidente da República as leis que disponham sobre servidores públicos da União e Territórios, seu regime jurídico, provimento de cargos, estabilidade e aposentadoria.","Art. 61, §1º, II, c.","iniciativa"),
(T5,["61"],"E","A iniciativa popular pode ser exercida pela apresentação à Câmara dos Deputados de projeto de lei subscrito por, no mínimo, cinco por cento do eleitorado nacional, distribuído por pelo menos cinco Estados.","Art. 61, §2º: um por cento do eleitorado nacional, distribuído pelo menos por cinco Estados, com não menos de três décimos por cento dos eleitores de cada um deles.","numero"),
(T5,["62"],"C","Em caso de relevância e urgência, o Presidente da República poderá adotar medidas provisórias, com força de lei, devendo submetê-las de imediato ao Congresso Nacional.","Art. 62, caput.","leitura"),
(T5,["62"],"E","É permitida a edição de medida provisória sobre matéria relativa a direito penal, desde que haja relevância e urgência.","Art. 62, §1º, I, b: vedada a edição de MP sobre direito penal, processual penal e processual civil.","pegadinha"),
(T5,["62"],"C","É vedada a edição de medida provisória sobre matéria relativa a nacionalidade, cidadania, direitos políticos, partidos políticos e direito eleitoral.","Art. 62, §1º, I, a.","leitura"),
(T5,["62"],"E","As medidas provisórias perderão eficácia, desde a edição, se não forem convertidas em lei no prazo de trinta dias, prorrogável uma vez por igual período.","Art. 62, §3º: sessenta dias, prorrogável uma vez por igual período.","numero"),
(T5,["62"],"C","O prazo de vigência da medida provisória suspende-se durante os períodos de recesso do Congresso Nacional.","Art. 62, §4º.","leitura"),
(T5,["62"],"E","Se a medida provisória não for apreciada em até trinta dias contados de sua publicação, entrará em regime de urgência.","Art. 62, §6º: quarenta e cinco dias; ficam sobrestadas as demais deliberações da Casa em que estiver tramitando.","numero"),
(T5,["62"],"C","As medidas provisórias terão sua votação iniciada na Câmara dos Deputados, cabendo a uma comissão mista de Deputados e Senadores examiná-las e emitir parecer antes de serem apreciadas, em sessão separada, pelo plenário de cada Casa.","Art. 62, §§8º e 9º.","competencia"),
(T5,["62"],"E","É permitida a reedição, na mesma sessão legislativa, de medida provisória que tenha perdido sua eficácia por decurso de prazo.","Art. 62, §10: vedada a reedição na mesma sessão legislativa.","pegadinha"),
(T5,["62"],"C","Aprovado projeto de lei de conversão alterando o texto original da medida provisória, esta manter-se-á integralmente em vigor até que seja sancionado ou vetado o projeto.","Art. 62, §12.","leitura"),
(T5,["62"],"C","A medida provisória que implique instituição ou majoração de impostos, ressalvados os impostos extrafiscais previstos no texto, só produzirá efeitos no exercício financeiro seguinte se tiver sido convertida em lei até o último dia daquele em que foi editada.","Art. 62, §2º.","leitura"),
(T5,["63"],"C","Não será admitido aumento da despesa prevista nos projetos de iniciativa exclusiva do Presidente da República, ressalvado o disposto no art. 166, §§3º e 4º.","Art. 63, I.","iniciativa"),
(T5,["64"],"C","A discussão e votação dos projetos de lei de iniciativa do Presidente da República, do STF e dos Tribunais Superiores terão início na Câmara dos Deputados.","Art. 64, caput.","competencia"),
(T5,["64"],"E","Se, solicitada urgência pelo Presidente da República, a Câmara e o Senado não se manifestarem em até sessenta dias, sobrestar-se-ão todas as demais deliberações legislativas da respectiva Casa.","Art. 64, §2º: quarenta e cinco dias.","numero"),
(T5,["65"],"C","O projeto de lei aprovado por uma Casa será revisto pela outra, em um só turno de discussão e votação, e enviado à sanção ou promulgação, se a Casa revisora o aprovar, ou arquivado, se o rejeitar.","Art. 65, caput.","leitura"),
(T5,["65"],"E","Sendo o projeto emendado pela Casa revisora, será enviado diretamente à sanção do Presidente da República.","Art. 65, p.ú.: voltará à Casa iniciadora.","pegadinha"),
(T5,["66"],"E","O Presidente da República dispõe do prazo de trinta dias úteis para sancionar ou vetar o projeto de lei.","Art. 66, §1º: quinze dias úteis, contados da data do recebimento.","numero"),
(T5,["66"],"C","Decorrido o prazo de quinze dias para sanção ou veto, o silêncio do Presidente da República importará sanção.","Art. 66, §3º (sanção tácita).","leitura"),
(T5,["66"],"E","O veto parcial poderá abranger palavras ou expressões isoladas de um dispositivo.","Art. 66, §2º: somente texto integral de artigo, parágrafo, inciso ou alínea.","pegadinha"),
(T5,["66"],"C","O veto será apreciado em sessão conjunta, dentro de trinta dias a contar de seu recebimento, só podendo ser rejeitado pelo voto da maioria absoluta dos Deputados e Senadores.","Art. 66, §4º.","quorum"),
(T5,["66"],"E","O veto será apreciado em sessão separada de cada Casa e só poderá ser rejeitado pelo voto de dois terços dos Deputados e Senadores.","Art. 66, §4º: sessão conjunta; maioria absoluta.","quorum"),
(T5,["66"],"C","Se a lei não for promulgada dentro de quarenta e oito horas pelo Presidente da República, nos casos de sanção tácita ou de rejeição do veto, o Presidente do Senado a promulgará e, se este não o fizer em igual prazo, caberá ao Vice-Presidente do Senado fazê-lo.","Art. 66, §7º.","competencia"),
(T5,["66"],"E","Esgotado sem deliberação o prazo para apreciação do veto, este será arquivado, mantendo-se o texto vetado.","Art. 66, §6º: o veto será colocado na ordem do dia da sessão imediata, sobrestadas as demais proposições, até sua votação final (trancamento da pauta).","pegadinha"),
(T5,["67"],"C","A matéria constante de projeto de lei rejeitado somente poderá constituir objeto de novo projeto, na mesma sessão legislativa, mediante proposta da maioria absoluta dos membros de qualquer das Casas do Congresso Nacional.","Art. 67.","quorum"),
(T5,["68"],"C","As leis delegadas serão elaboradas pelo Presidente da República, que deverá solicitar a delegação ao Congresso Nacional, a qual terá a forma de resolução.","Art. 68, caput e §2º.","leitura"),
(T5,["68"],"E","Podem ser objeto de delegação ao Presidente da República a legislação sobre nacionalidade, cidadania, direitos individuais, políticos e eleitorais, desde que haja resolução do Congresso Nacional.","Art. 68, §1º, II: não serão objeto de delegação.","pegadinha"),
(T5,["68"],"C","Se a resolução de delegação determinar a apreciação do projeto pelo Congresso Nacional, este a fará em votação única, vedada qualquer emenda.","Art. 68, §3º.","leitura"),
(T5,["69"],"C","As leis complementares serão aprovadas por maioria absoluta.","Art. 69.","quorum"),
(T5,["69"],"E","As leis complementares serão aprovadas por três quintos dos membros de cada Casa.","Art. 69: maioria absoluta.","quorum"),
(T5,["70"],"C","A fiscalização contábil, financeira, orçamentária, operacional e patrimonial da União e das entidades da administração direta e indireta será exercida pelo Congresso Nacional, mediante controle externo, e pelo sistema de controle interno de cada Poder.","Art. 70, caput.","competencia"),
(T5,["70"],"E","Prestará contas apenas a pessoa jurídica de direito público que utilize, arrecade, guarde, gerencie ou administre dinheiros, bens e valores públicos.","Art. 70, p.ú.: qualquer pessoa física ou jurídica, pública ou privada.","generalizacao"),
(T5,["71"],"C","O controle externo, a cargo do Congresso Nacional, será exercido com o auxílio do Tribunal de Contas da União.","Art. 71, caput.","competencia"),
(T5,["71"],"E","Compete ao Tribunal de Contas da União julgar as contas anuais do Presidente da República.","Art. 71, I e art. 49, IX: o TCU apenas aprecia as contas, mediante parecer prévio, em sessenta dias; o julgamento é do Congresso Nacional.","competencia"),
(T5,["71"],"C","As decisões do Tribunal de Contas da União de que resulte imputação de débito ou multa terão eficácia de título executivo.","Art. 71, §3º.","leitura"),
(T5,["71"],"E","No caso de contrato, o ato de sustação será adotado diretamente pelo Tribunal de Contas da União.","Art. 71, §1º: pelo Congresso Nacional, que solicitará ao Executivo as medidas cabíveis; se ambos não agirem em noventa dias, o Tribunal decidirá (§2º).","competencia"),
(T5,["73"],"C","O Tribunal de Contas da União é integrado por nove Ministros.","Art. 73, caput.","numero"),
(T5,["73"],"E","Dos Ministros do Tribunal de Contas da União, um terço será escolhido pelo Congresso Nacional e dois terços pelo Presidente da República, com aprovação do Senado Federal.","Art. 73, §2º: um terço pelo Presidente, com aprovação do Senado (dois alternadamente dentre auditores e membros do MP junto ao Tribunal); dois terços pelo Congresso.","numero"),
(T5,["74"],"C","Qualquer cidadão, partido político, associação ou sindicato é parte legítima para, na forma da lei, denunciar irregularidades ou ilegalidades perante o Tribunal de Contas da União.","Art. 74, §2º.","leitura"),
(T5,["75"],"E","Os Tribunais de Contas dos Estados serão integrados por cinco Conselheiros.","Art. 75, p.ú.: sete Conselheiros.","numero"),
# ---------- M4-6: regime jurídico-constitucional dos parlamentares ----------
(T6,["53"],"C","Os Deputados e Senadores são invioláveis, civil e penalmente, por quaisquer de suas opiniões, palavras e votos.","Art. 53, caput (imunidade material).","leitura"),
(T6,["53"],"E","A inviolabilidade de Deputados e Senadores por suas opiniões, palavras e votos exige que estas sejam proferidas no recinto do Congresso Nacional.","Art. 53, caput não exige local; o STF exige nexo com o exercício do mandato (fora do recinto), dispensando-o nas manifestações no recinto.","jurisprudencia"),
(T6,["53"],"C","Desde a expedição do diploma, os membros do Congresso Nacional não poderão ser presos, salvo em flagrante de crime inafiançável.","Art. 53, §2º (imunidade formal quanto à prisão).","leitura"),
(T6,["53"],"E","Em caso de prisão em flagrante de crime inafiançável de parlamentar, os autos serão remetidos à Casa respectiva em até quarenta e oito horas para que, pelo voto da maioria simples, resolva sobre a prisão.","Art. 53, §2º: vinte e quatro horas; voto da maioria dos membros da Casa.","numero"),
(T6,["53"],"C","Os Deputados e Senadores, desde a expedição do diploma, serão submetidos a julgamento perante o Supremo Tribunal Federal.","Art. 53, §1º (foro por prerrogativa de função; STF limitou-o a crimes cometidos no exercício e em razão do cargo — AP 937).","competencia"),
(T6,["53"],"C","Recebida a denúncia contra o Senador ou Deputado por crime ocorrido após a diplomação, o STF dará ciência à Casa respectiva, que, por iniciativa de partido político nela representado e pelo voto da maioria de seus membros, poderá, até a decisão final, sustar o andamento da ação.","Art. 53, §3º.","quorum"),
(T6,["53"],"E","O pedido de sustação do andamento da ação penal contra parlamentar será apreciado pela Casa respectiva no prazo improrrogável de sessenta dias.","Art. 53, §4º: quarenta e cinco dias.","numero"),
(T6,["53"],"C","A sustação do processo penal contra parlamentar suspende a prescrição, enquanto durar o mandato.","Art. 53, §5º.","leitura"),
(T6,["53"],"E","Os Deputados e Senadores são obrigados a testemunhar sobre informações recebidas em razão do exercício do mandato, mas não sobre as pessoas que lhes confiaram informações.","Art. 53, §6º: não serão obrigados a testemunhar nem sobre informações nem sobre as pessoas.","pegadinha"),
(T6,["53"],"C","A incorporação às Forças Armadas de Deputados e Senadores, embora militares e ainda que em tempo de guerra, dependerá de prévia licença da Casa respectiva.","Art. 53, §7º.","leitura"),
(T6,["53"],"E","As imunidades de Deputados e Senadores ficam suspensas durante o estado de sítio, independentemente de deliberação da Casa.","Art. 53, §8º: subsistem; só podem ser suspensas pelo voto de 2/3 da Casa, para atos praticados fora do recinto incompatíveis com a execução da medida.","pegadinha"),
(T6,["54"],"C","Desde a expedição do diploma, os Deputados e Senadores não poderão firmar ou manter contrato com pessoa jurídica de direito público, autarquia, empresa pública, sociedade de economia mista ou empresa concessionária de serviço público, salvo quando o contrato obedecer a cláusulas uniformes.","Art. 54, I, a.","leitura"),
(T6,["54"],"C","Desde a posse, os Deputados e Senadores não poderão ser titulares de mais de um cargo ou mandato público eletivo.","Art. 54, II, d.","leitura"),
(T6,["55"],"C","Perderá o mandato o Deputado ou Senador que deixar de comparecer, em cada sessão legislativa, à terça parte das sessões ordinárias da Casa a que pertencer, salvo licença ou missão por esta autorizada.","Art. 55, III.","numero"),
(T6,["55"],"E","Perderá o mandato o Deputado ou Senador que deixar de comparecer, em cada sessão legislativa, à metade das sessões ordinárias da Casa.","Art. 55, III: terça parte.","numero"),
(T6,["55"],"C","Perderá o mandato o Deputado ou Senador que sofrer condenação criminal em sentença transitada em julgado.","Art. 55, VI.","leitura"),
(T6,["55"],"E","Nos casos de perda de mandato por infringência às proibições do art. 54, por procedimento incompatível com o decoro parlamentar ou por condenação criminal transitada em julgado, a perda será declarada pela Mesa da Casa respectiva.","Art. 55, §2º: nesses casos (I, II e VI) a perda é decidida pelo Plenário, por maioria absoluta; a Mesa declara a perda nos casos III a V (§3º).","pegadinha"),
(T6,["55"],"C","Nos casos de perda do mandato por infringência às proibições do art. 54, por quebra de decoro ou por condenação criminal transitada em julgado, a perda será decidida pela Câmara dos Deputados ou pelo Senado Federal, por maioria absoluta, mediante provocação da respectiva Mesa ou de partido político representado no Congresso Nacional, assegurada ampla defesa.","Art. 55, §2º (redação da EC 76/2013: voto ostensivo).","quorum"),
(T6,["55"],"C","Nos casos de perda de mandato por ausência a sessões, por perda ou suspensão de direitos políticos ou quando decretada pela Justiça Eleitoral, a perda será declarada pela Mesa da Casa respectiva, de ofício ou mediante provocação, assegurada ampla defesa.","Art. 55, §3º (incisos III a V).","competencia"),
(T6,["55"],"C","A renúncia de parlamentar submetido a processo que vise ou possa levar à perda do mandato terá os efeitos suspensos até as deliberações finais da Casa respectiva.","Art. 55, §4º.","leitura"),
(T6,["55"],"C","É incompatível com o decoro parlamentar, além dos casos definidos no regimento interno, o abuso das prerrogativas asseguradas a membro do Congresso Nacional ou a percepção de vantagens indevidas.","Art. 55, §1º.","leitura"),
(T6,["56"],"C","Não perderá o mandato o Deputado ou Senador investido no cargo de Ministro de Estado, Governador de Território, Secretário de Estado, do Distrito Federal, de Território, de Prefeitura de Capital ou chefe de missão diplomática temporária.","Art. 56, I.","leitura"),
(T6,["56"],"E","Não perderá o mandato o Deputado ou Senador licenciado para tratar, sem remuneração, de interesse particular, ainda que o afastamento ultrapasse cento e vinte dias por sessão legislativa.","Art. 56, II: desde que o afastamento não ultrapasse cento e vinte dias por sessão legislativa.","numero"),
(T6,["56"],"C","O suplente será convocado nos casos de vaga, de investidura em funções previstas no art. 56 ou de licença superior a cento e vinte dias.","Art. 56, §1º.","numero"),
(T6,["56"],"E","Ocorrendo vaga e não havendo suplente, far-se-á eleição para preenchê-la se faltarem mais de seis meses para o término do mandato.","Art. 56, §2º: mais de quinze meses.","numero"),
(T6,["56"],"C","Na hipótese de investidura em cargo de Ministro de Estado, o Deputado ou Senador poderá optar pela remuneração do mandato.","Art. 56, §3º.","leitura"),
]
